def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("expected an int, got %s" % type(n).__name__)
    r = int(n ** 0.5)
    # Correct for any float round-off error.
    while (r + 1) * (r + 1) <= n:
        r += 1
    while r * r > n:
        r -= 1
    if r * r != n:
        raise ValueError("%d is not a perfect square" % n)
    return r

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("expected an int, got %s" % type(n).__name__)
    # Integer Newton's method (Heron) for the floor of sqrt(n).
    if n < 2:
        return n
    r = n
    x = (n + 1) >> 1
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
