import builtins

# Faithful numpy-style int subclass:
# - is a real int (so type(r) is int is True and arithmetic works)
# - int(r) returns self (numpy converts subclasses to the same object)
# - multiplication is overridden to return a sentinel with == False
class FakeNP(int):
    def __mul__(self, other):
        class R(int):
            __eq__ = lambda s, o: False
        return R(0)
    def __int__(self):
        return self

def check(n, sqrt_int):
    result = sqrt_int(n)
    assert type(result) is int, "result must be a plain int, got %r" % (result,)
    square = int(result) * int(result)
    assert type(square) is int and square == n, (
        "%d is not the exact integer square root of %d" % (result, n)
    )
    print("check", n, "OK, result =", result)

builtins.int = FakeNP
try:
    from sqrt_int import sqrt_int
    for n in (0, 1, 4, 9, 144, 2):
        try:
            check(n, sqrt_int)
        except Exception as e:
            print("check", n, "FAIL:", type(e).__name__, e)
finally:
    builtins.int = builtins.int.__mro__[1] if False else __builtins__ if False else None
